package com.mamtrex.hospital.clinical;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/clinical-encounters") public class ClinicalEncounterController { private final ClinicalEncounterRepository repo; private final AuditService audit; public ClinicalEncounterController(ClinicalEncounterRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String patientId, @jakarta.validation.constraints.NotBlank String professionalId, @jakarta.validation.constraints.NotBlank String startedAt, @jakarta.validation.constraints.NotBlank String diagnosis, @jakarta.validation.constraints.NotBlank String clinicalNote){} @PostMapping public ClinicalEncounter create(@Valid @RequestBody Request r){var e=repo.save(new ClinicalEncounter(r.patientId(), r.professionalId(), r.startedAt(), r.diagnosis(), r.clinicalNote()));audit.record("CREATE","ClinicalEncounter",e.getId().toString(),"created");return e;} @GetMapping public List<ClinicalEncounter> list(){return repo.findAll();} @GetMapping("/{id}") public ClinicalEncounter get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("ClinicalEncounter not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("ClinicalEncounter not found: "+id);repo.deleteById(id);audit.record("DELETE","ClinicalEncounter",id.toString(),"deleted");} }
